'use client'
import React, { useEffect, useRef, useState } from 'react'
import gsap from 'gsap'
import { Howler } from 'howler'
import { BasePhaseProps } from '@/lib/types'
import { playStarPing } from '@/lib/sounds'

interface StarFacetProps {
    filled: boolean
    flashing?: boolean
    shockwave?: boolean
    size?: number
}

/**
 * 3D Faceted Star with authentic beveled geometry and glowing core
 */
function FacetedStar({ filled, flashing = false, shockwave = false, size = 52 }: StarFacetProps) {
    return (
        <div
            style={{
                position: 'relative',
                width: size,
                height: size,
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
            }}
        >
            {/* Expanding shockwave ring on ignition */}
            {shockwave && (
                <div
                    className="star-shockwave"
                    style={{
                        position: 'absolute',
                        width: size * 1.4,
                        height: size * 1.4,
                        borderRadius: '50%',
                        border: '2px solid rgba(255, 215, 0, 0.9)',
                        boxShadow: '0 0 20px rgba(255, 215, 0, 0.8), inset 0 0 10px rgba(255, 255, 255, 0.8)',
                        pointerEvents: 'none',
                    }}
                />
            )}

            <svg
                width={size}
                height={size}
                viewBox="0 0 100 100"
                className={flashing ? 'gta-wanted-flash' : ''}
                style={{
                    filter: filled
                        ? 'drop-shadow(0 0 10px rgba(255, 255, 255, 0.95)) drop-shadow(0 0 22px rgba(245, 166, 35, 0.8))'
                        : 'drop-shadow(0 2px 6px rgba(0, 0, 0, 0.8))',
                    transition: 'transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275)',
                    transform: filled ? 'scale(1)' : 'scale(0.92)',
                }}
            >
                <defs>
                    {/* Gold faceted gradients */}
                    <linearGradient id="facetGoldLight" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="#fff6d1" />
                        <stop offset="100%" stopColor="#f5a623" />
                    </linearGradient>
                    <linearGradient id="facetGoldDark" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="#e59819" />
                        <stop offset="100%" stopColor="#a36200" />
                    </linearGradient>

                    {/* Dark empty socket gradients */}
                    <linearGradient id="socketDark" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="#1c1c24" />
                        <stop offset="100%" stopColor="#0c0c10" />
                    </linearGradient>
                </defs>

                {filled ? (
                    /* 3D 10-facet beveled star */
                    <g>
                        {/* Outer glow stroke */}
                        <polygon
                            points="50,5 62,35 95,35 68,55 79,88 50,68 21,88 32,55 5,35 38,35"
                            fill="url(#facetGoldLight)"
                            stroke="#ffffff"
                            strokeWidth="1.5"
                        />
                        {/* Darker alternating facets for 3D depth */}
                        <polygon points="50,5 50,68 62,35" fill="url(#facetGoldDark)" opacity="0.6" />
                        <polygon points="95,35 50,68 68,55" fill="url(#facetGoldDark)" opacity="0.65" />
                        <polygon points="79,88 50,68 50,68" fill="url(#facetGoldDark)" opacity="0.7" />
                        <polygon points="21,88 50,68 32,55" fill="url(#facetGoldDark)" opacity="0.6" />
                        <polygon points="5,35 50,68 38,35" fill="url(#facetGoldDark)" opacity="0.65" />

                        {/* Inner radiant diamond flare */}
                        <circle cx="50" cy="50" r="10" fill="#ffffff" opacity="0.85" filter="blur(2px)" />
                    </g>
                ) : (
                    /* Empty star frame with subtle metallic rim */
                    <g>
                        <polygon
                            points="50,5 62,35 95,35 68,55 79,88 50,68 21,88 32,55 5,35 38,35"
                            fill="url(#socketDark)"
                            stroke="rgba(255, 255, 255, 0.28)"
                            strokeWidth="2"
                        />
                        {/* Subtle inner facet creases */}
                        <line x1="50" y1="5" x2="50" y2="68" stroke="rgba(255, 255, 255, 0.1)" strokeWidth="1" />
                        <line x1="95" y1="35" x2="50" y2="68" stroke="rgba(255, 255, 255, 0.1)" strokeWidth="1" />
                        <line x1="79" y1="88" x2="50" y2="68" stroke="rgba(255, 255, 255, 0.1)" strokeWidth="1" />
                        <line x1="21" y1="88" x2="50" y2="68" stroke="rgba(255, 255, 255, 0.1)" strokeWidth="1" />
                        <line x1="5" y1="35" x2="50" y2="68" stroke="rgba(255, 255, 255, 0.1)" strokeWidth="1" />
                    </g>
                )}
            </svg>
        </div>
    )
}

const TIER_MESSAGES = [
    'POLICE SYSTEM INITIALIZED',
    'LEVEL 1 // SUSPECT IDENTIFIED',
    'LEVEL 2 // LOCAL UNITS DISPATCHED',
    'LEVEL 3 // STATE PATROL CONVERGING',
    'LEVEL 4 // AIR SUPPORT DEPLOYED',
    'LEVEL 5 // MAXIMUM WANTED LEVEL',
]

export default function WantedStars({ onComplete, sounds }: BasePhaseProps) {
    const containerRef = useRef<HTMLDivElement | null>(null)
    const redStrobeRef = useRef<HTMLDivElement | null>(null)
    const blueStrobeRef = useRef<HTMLDivElement | null>(null)
    const searchlightRef = useRef<HTMLDivElement | null>(null)
    const flashRef = useRef<HTMLDivElement | null>(null)
    const badgeRef = useRef<HTMLDivElement | null>(null)

    const [starCount, setStarCount] = useState<number>(0)
    const [shockwaveIdx, setShockwaveIdx] = useState<number>(-1)
    const [isMaxWanted, setIsMaxWanted] = useState<boolean>(false)
    const completedRef = useRef<boolean>(false)

    const triggerComplete = () => {
        if (completedRef.current) return
        completedRef.current = true
        onComplete()
    }

    useEffect(() => {
        // Start siren loop cleanly
        const startAudio = async () => {
            try {
                if (Howler && Howler.ctx && Howler.ctx.state !== 'running') {
                    await Howler.ctx.resume()
                }
                const siren = sounds?.siren
                if (siren) {
                    siren.stop()
                    siren.volume(0.48)
                    siren.play()
                }
            } catch (err) {
                console.warn('Audio notice:', err)
            }
        }
        startAudio()

        // Continuous searchlight sweep
        if (searchlightRef.current) {
            gsap.to(searchlightRef.current, {
                x: '130%',
                duration: 1.8,
                repeat: -1,
                yoyo: true,
                ease: 'power1.inOut',
            })
        }

        // Alternating red/blue police strobes
        const strobeTl = gsap.timeline({ repeat: -1 })
        if (redStrobeRef.current) {
            strobeTl
                .to(redStrobeRef.current, { opacity: 0.75, duration: 0.05 })
                .to(redStrobeRef.current, { opacity: 0.08, duration: 0.04 })
                .to(redStrobeRef.current, { opacity: 0.9, duration: 0.06 })
                .to(redStrobeRef.current, { opacity: 0, duration: 0.12 })
        }
        if (blueStrobeRef.current) {
            strobeTl
                .to(blueStrobeRef.current, { opacity: 0.75, duration: 0.05 }, '-=0.08')
                .to(blueStrobeRef.current, { opacity: 0.08, duration: 0.04 })
                .to(blueStrobeRef.current, { opacity: 0.9, duration: 0.06 })
                .to(blueStrobeRef.current, { opacity: 0, duration: 0.14 })
        }

        // Entrance animation for HUD badge
        if (badgeRef.current) {
            gsap.fromTo(
                badgeRef.current,
                { opacity: 0, scale: 0.88, y: -20 },
                { opacity: 1, scale: 1, y: 0, duration: 0.45, ease: 'back.out(1.4)' }
            )
        }

        // Master fast & punchy timeline (total duration: ~3.8s)
        const masterTl = gsap.timeline({
            onComplete: triggerComplete,
        })

        // Star 1 at 0.5s
        masterTl.to({}, {
            duration: 0.01,
            onStart: () => {
                setStarCount(1)
                setShockwaveIdx(0)
                playStarPing(0)
            },
        }, 0.5)

        // Star 2 at 1.0s
        masterTl.to({}, {
            duration: 0.01,
            onStart: () => {
                setStarCount(2)
                setShockwaveIdx(1)
                playStarPing(1)
            },
        }, 1.0)

        // Star 3 at 1.5s
        masterTl.to({}, {
            duration: 0.01,
            onStart: () => {
                setStarCount(3)
                setShockwaveIdx(2)
                playStarPing(2)
            },
        }, 1.5)

        // Star 4 at 2.0s
        masterTl.to({}, {
            duration: 0.01,
            onStart: () => {
                setStarCount(4)
                setShockwaveIdx(3)
                playStarPing(3)
            },
        }, 2.0)

        // Star 5 (Max Wanted slam) at 2.5s
        masterTl.to({}, {
            duration: 0.01,
            onStart: () => {
                setStarCount(5)
                setShockwaveIdx(4)
                setIsMaxWanted(true)
                playStarPing(4)

                // White flash burst
                if (flashRef.current) {
                    gsap.fromTo(
                        flashRef.current,
                        { opacity: 0.85 },
                        { opacity: 0, duration: 0.35, ease: 'power2.out' }
                    )
                }

                // Dramatic screen rumble on 5th star
                if (containerRef.current) {
                    gsap.fromTo(
                        containerRef.current,
                        { x: -8, y: -4 },
                        {
                            x: 8,
                            y: 4,
                            duration: 0.035,
                            repeat: 8,
                            yoyo: true,
                            ease: 'none',
                            onComplete: () => {
                                if (containerRef.current) {
                                    gsap.set(containerRef.current, { x: 0, y: 0 })
                                }
                            },
                        }
                    )
                }
            },
        }, 2.5)

        // Hold 5-star glory pulse from 2.5s to 3.8s
        masterTl.to({}, { duration: 1.3 }, 2.5)

        // Quick skip listeners
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.code === 'Space' || e.code === 'Enter' || e.code === 'Escape') {
                triggerComplete()
            }
        }
        window.addEventListener('keydown', handleKeyDown)

        return () => {
            masterTl.kill()
            strobeTl.kill()
            window.removeEventListener('keydown', handleKeyDown)
            if (searchlightRef.current) gsap.killTweensOf(searchlightRef.current)
            if (containerRef.current) gsap.killTweensOf(containerRef.current)
            if (flashRef.current) gsap.killTweensOf(flashRef.current)
            if (badgeRef.current) gsap.killTweensOf(badgeRef.current)
        }
    }, [sounds])

    return (
        <div
            ref={containerRef}
            onClick={triggerComplete}
            style={{
                position: 'fixed',
                inset: 0,
                background: '#060608',
                zIndex: 95,
                overflow: 'hidden',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                userSelect: 'none',
                cursor: 'pointer',
            }}
        >
            {/* Red Police Strobe */}
            <div
                ref={redStrobeRef}
                style={{
                    position: 'absolute',
                    inset: 0,
                    background:
                        'radial-gradient(ellipse at 12% 50%, rgba(255, 20, 20, 0.75) 0%, rgba(180, 0, 0, 0.25) 45%, transparent 70%)',
                    opacity: 0,
                    mixBlendMode: 'screen',
                }}
            />

            {/* Blue Police Strobe */}
            <div
                ref={blueStrobeRef}
                style={{
                    position: 'absolute',
                    inset: 0,
                    background:
                        'radial-gradient(ellipse at 88% 50%, rgba(0, 110, 255, 0.75) 0%, rgba(0, 70, 200, 0.25) 45%, transparent 70%)',
                    opacity: 0,
                    mixBlendMode: 'screen',
                }}
            />

            {/* Helicopter Searchlight Beam */}
            <div
                ref={searchlightRef}
                style={{
                    position: 'absolute',
                    top: '-20%',
                    left: '-30%',
                    width: '60%',
                    height: '140%',
                    background:
                        'radial-gradient(ellipse at center, rgba(255, 255, 255, 0.16) 0%, transparent 60%)',
                    transform: 'rotate(-25deg)',
                    pointerEvents: 'none',
                    mixBlendMode: 'screen',
                }}
            />

            {/* Subtle Vignette */}
            <div className="heavy-vignette" />

            {/* Screen Flash on Max Wanted */}
            <div
                ref={flashRef}
                style={{
                    position: 'absolute',
                    inset: 0,
                    background: '#ffffff',
                    opacity: 0,
                    pointerEvents: 'none',
                    zIndex: 120,
                }}
            />

            {/* ═══ CENTRAL WANTED HUD BADGE ═══ */}
            <div
                ref={badgeRef}
                style={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    gap: '20px',
                    zIndex: 110,
                    padding: '28px 44px',
                    background: 'rgba(10, 10, 14, 0.88)',
                    backdropFilter: 'blur(16px)',
                    WebkitBackdropFilter: 'blur(16px)',
                    border: '1px solid rgba(255, 255, 255, 0.15)',
                    borderTop: isMaxWanted ? '3px solid #ff2a2a' : '3px solid #f5a623',
                    borderBottom: isMaxWanted ? '1px solid #ff2a2a' : '1px solid rgba(245, 166, 35, 0.4)',
                    boxShadow: isMaxWanted
                        ? '0 20px 60px rgba(0, 0, 0, 0.95), 0 0 40px rgba(255, 42, 42, 0.35)'
                        : '0 20px 60px rgba(0, 0, 0, 0.9), 0 0 30px rgba(245, 166, 35, 0.18)',
                    transition: 'border-color 0.3s ease, box-shadow 0.3s ease',
                    maxWidth: '680px',
                    width: '92%',
                }}
            >
                {/* Header Tagline */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <div
                        style={{
                            width: '8px',
                            height: '8px',
                            background: isMaxWanted ? '#ff2a2a' : '#f5a623',
                            boxShadow: isMaxWanted ? '0 0 10px #ff2a2a' : '0 0 8px #f5a623',
                        }}
                    />
                    <span
                        style={{
                            fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                            fontSize: '0.82rem',
                            letterSpacing: '0.35em',
                            color: isMaxWanted ? '#ff4d4d' : 'rgba(255, 255, 255, 0.65)',
                            textTransform: 'uppercase',
                            fontWeight: 700,
                        }}
                    >
                        LOS SANTOS POLICE DEPT // TACTICAL ADVISORY
                    </span>
                </div>

                {/* 5 STARS ROW */}
                <div
                    style={{
                        display: 'flex',
                        gap: '18px',
                        alignItems: 'center',
                        justifyContent: 'center',
                        padding: '10px 0',
                    }}
                >
                    {[0, 1, 2, 3, 4].map((i) => {
                        const isFilled = i < starCount
                        const isCurrentShockwave = shockwaveIdx === i

                        return (
                            <div
                                key={i}
                                style={{
                                    animation: isFilled ? 'starPopIn 0.26s cubic-bezier(0.175, 0.885, 0.32, 1.3)' : 'none',
                                }}
                            >
                                <FacetedStar
                                    filled={isFilled}
                                    flashing={isMaxWanted}
                                    shockwave={isCurrentShockwave}
                                    size={56}
                                />
                            </div>
                        )
                    })}
                </div>

                {/* Dynamic Status Readout */}
                <div style={{ textAlign: 'center' }}>
                    <div
                        style={{
                            fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                            fontSize: 'clamp(1.2rem, 3vw, 1.7rem)',
                            letterSpacing: '0.14em',
                            color: isMaxWanted ? '#ff3b3b' : '#ffffff',
                            textTransform: 'uppercase',
                            textShadow: isMaxWanted
                                ? '0 0 20px rgba(255, 59, 59, 0.8)'
                                : '0 2px 10px rgba(0, 0, 0, 0.8)',
                            transition: 'color 0.2s ease',
                        }}
                    >
                        {TIER_MESSAGES[starCount] || TIER_MESSAGES[0]}
                    </div>
                </div>
            </div>

            {/* Bottom Skip Indicator */}
            <div
                style={{
                    position: 'absolute',
                    bottom: '32px',
                    fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                    fontSize: '0.78rem',
                    letterSpacing: '0.28em',
                    color: 'rgba(255, 255, 255, 0.4)',
                    textTransform: 'uppercase',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '10px',
                    zIndex: 110,
                }}
            >
                <span className="smooth-pulse">[ PRESS SPACE OR CLICK TO ENTER ]</span>
            </div>

            <style jsx>{`
                @keyframes starPopIn {
                    0% {
                        transform: scale(0.2);
                        opacity: 0;
                    }
                    65% {
                        transform: scale(1.35);
                    }
                    100% {
                        transform: scale(1);
                        opacity: 1;
                    }
                }
            `}</style>
        </div>
    )
}
